// Salida del agente -> cuerpo de POST /bo-api/proposals (docs/integracion.md, apartado 5)
// customer_reply va dentro de proposed_action porque bo_agent_proposals no tiene columna para él.
const p = $json.output;
const ticketId = $('Datos para el agente').first().json.ticket_id;
const confidence = Math.min(1, Math.max(0, Number(p.confidence) || 0));
// Telegram lee el mensaje como Markdown: _ * ` [ sueltos lo rompen (dano_envio, pendiente_pago...)
const md = s => String(s ?? '').replace(/([_*`\[])/g, '\\$1');
const mensaje = [
  'Incidencia ' + ticketId + ' · ' + md(p.case_type) + ' · prioridad ' + md(p.priority) + ' · confianza ' + confidence,
  '',
  'Propuesta: ' + md(p.proposed_action),
  '',
  'Respuesta al cliente: ' + md(p.customer_reply),
  '',
  'Por qué: ' + md(p.justification),
  '',
  'Riesgos: ' + md(p.risks || 'ninguno'),
].join('\n');
const incidencia = $('Validar').first().json.entity_id;
const aviso = 'Sobre tu incidencia ' + incidencia + ':\n\n' + md(p.customer_reply);
return { json: {
  priority: p.priority,
  customer_reply: p.customer_reply,
  mensaje_telegram: mensaje,
  aviso_cliente: aviso,
  body: {
    ticket_id: ticketId,
    case_type: p.case_type,
    consulted_data: p.consulted_data,
    proposed_action: p.proposed_action + ' | Respuesta al cliente: "' + p.customer_reply + '"',
    justification: p.justification,
    confidence,
    risks: p.risks || null,
  },
} };

// El ticket ya está creado: aquí solo falta la propuesta (docs/integracion.md, apartado 4)
const msg = String($json.error?.message ?? $json.error ?? 'El agente no respondió');
const formato = /parse|format|schema|json/i.test(msg);
return { json: {
  result: 'error',
  error_type: formato ? 'salida_agente_no_valida' : 'agente_no_disponible',
  message: 'Agente: ' + msg.slice(0, 480),
} };
